"""Friday Night Firefight: attack modifiers, fumble tables, cover, shotguns, area weapons, suppressive
fire, melee against a defender, martial arts and mono-edges, and the GM's encounter tools."""
import asyncio, json, sys, os, re
from playwright.async_api import async_playwright
from harness import *

SHOTS=os.path.join(OUT,"combat");os.makedirs(SHOTS,exist_ok=True)
def shot(n):return os.path.join(SHOTS,n)
SEQ="window.__q=[];d10x=()=>[window.__q.length?window.__q.shift():5];0"
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pl=await page(b,"P","player.html");pl.set_default_timeout(8000)
        await make_runner(pl,"Razor")
        await pl.click(".card:has-text('Razor') >> text=Open sheet");await pl.wait_for_timeout(300)
        # rules helpers
        ok(await pl.evaluate("[fumbleArea('Attack · Knife'),fumbleArea('Handgun (REF)'),fumbleArea('Athletics (REF)'),fumbleArea('Basic Tech (TECH)'),fumbleArea('Seduction (EMP)'),fumbleArea('Awareness/Notice (INT)'),fumbleArea('Intimidate (COOL)'),fumbleArea('Martial Art: Karate (REF)')]")==["combat","combat","athletics","tech","emp","int",None,"combat"],"each skill finds its fumble table by its stat")
        ok(await pl.evaluate("hitSP(14,{cover:25})")==28 and await pl.evaluate("hitSP(18,{mono:true})")==6 and await pl.evaluate("hitSP(18,{mono:true,hard:true})")==12 and await pl.evaluate("hitSP(20,{ap:true})")==10,"cover combines by the proportional rule; mono-edges count soft armor at 1/3, hard at 2/3; AP halves")
        ok(await pl.evaluate("[shotgunAt(15).dmg,shotgunAt(20).dmg,shotgunAt(25).dmg,shotgunAt(20).w]")==["4D6","3D6","2D6",2],"shotgun pattern by range")
        # give her the new toys
        await pl.evaluate("""(()=>{const c=curChar();c.eb=50000;c.skills['Heavy Weapons']={c:0,p:4,b:0};c.skills['Athletics']={c:4,p:0,b:0};saveChar(c,true);render()})()""")
        await pl.click("[data-act=tab][data-t=combat]");await pl.wait_for_timeout(150)
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Weapons]");await pl.wait_for_timeout(200)
        idx=await pl.evaluate("Object.fromEntries(['Grenade (fragmentation)','Grenade launcher','C-6 plastic explosive (1kg)','Molotov cocktail','Sternmeyer Stakeout 10','Arasaka Rapid Assault 12','Monokatana','Militech Arms RPG-A','Grenade (gas)'].map(n=>[n,WEAPONS.findIndex(r=>r[0]===n)]))")
        ok(all(v>=0 for v in idx.values()),"the new heavy weapons are in the shop %s"%idx)
        ok(await pl.evaluate("WEAPONS.find(r=>r[0]==='Militech Arms RPG-A')[10]")==7500,"RPG-A at the book's 7,500eb")
        for n in ['Grenade (fragmentation)','Grenade (fragmentation)','Grenade launcher','C-6 plastic explosive (1kg)','C-6 plastic explosive (1kg)','Molotov cocktail','Sternmeyer Stakeout 10','Arasaka Rapid Assault 12','Monokatana','Grenade (gas)']:
            await pl.click(f"[data-act=buy][data-k=w][data-i='{idx[n]}']");await pl.wait_for_timeout(60)
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        g=await pl.evaluate("curChar().weapons.filter(w=>w.name==='Grenade (fragmentation)').map(w=>[w.shots,w.ammo])");ok(g==[["2",2]],"two grenades stack into one entry carrying 2 (%s)"%g)
        ok(await pl.evaluate("curChar().weapons.find(w=>w.name==='C-6 plastic explosive (1kg)').ammo")==2,"two kilos of C-6")
        W=await pl.evaluate("Object.fromEntries(curChar().weapons.map(w=>[w.name,w.id]))")
        pis=await pl.evaluate("curChar().weapons.find(w=>w.type==='P').id")
        # modifiers
        await pl.click(f".it[data-info='own:weapons:{pis}'] [data-act=atk-open]");await pl.wait_for_timeout(200)
        base0=await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).reduce((a,m)=>a+m[1],0)")
        await pl.click("summary >> text=Situation")
        await pl.click("[data-act=atk-sit][data-v=ambush]");await pl.click("[data-act=atk-sit][data-v=moving10]");await pl.click("[data-act=atk-sit][data-v=moving12]");await pl.wait_for_timeout(100)
        s=await pl.evaluate("ui.atk.sits");ok("moving12" in s and "moving10" not in s,"only one moving-target penalty at a time")
        b1=await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).reduce((a,m)=>a+m[1],0)");ok(b1==base0+5-4,"ambush +5, target moving REF > 12 −4 (%d → %d)"%(base0,b1))
        await pl.click("[data-act=atk-aimturns][data-v='3']");await pl.click("[data-act=atk-sit][data-v=laser]");await pl.wait_for_timeout(100)
        m2=await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).map(m=>m[0])");b2=await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).reduce((a,m)=>a+m[1],0)");ok(b2==b1+4,"aiming 3 turns +3 and a laser sight +1")
        await pl.click("[data-act=atk-sit][data-v=fastdraw]");await pl.wait_for_timeout(100)
        print(await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk)"));b3=await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).reduce((a,m)=>a+m[1],0)");m3=await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).map(m=>m[0])");ok(b3==b1-3-(1 if any("Targeting scope" in x for x in m2) else 0) and not any(("Aiming" in x or "Laser" in x or "scope" in x) for x in m3),"a fast draw is −3 and cancels aiming, sights and scopes (%d)"%b3)
        await pl.click("[data-act=atk-action][data-v='2']");await pl.wait_for_timeout(100)
        ok(await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{pis}'),ui.atk).reduce((a,m)=>a+m[1],0)")==b3-3,"a second action this turn is −3")
        await pl.screenshot(path=shot("atk-mods.png"))
        await pl.evaluate("ui.atk.sits=[];ui.atk.aimTurns=0;ui.atk.action=1;renderModal()")
        # fumble with a pistol: the combat fumble table
        await pl.evaluate("d10x=()=>[1];window.__r=Math.random;Math.random=()=>0.75;0")
        await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150);await pl.evaluate("Math.random=window.__r")
        r=await pl.evaluate("ui.atk.last");ok(r["fumbleRoll"]["r"]==8 and "wound yourself" in r["fumbleRoll"]["text"] and "you hit yourself" in r["note"].lower(),"a pistol fumble rolls the combat fumble table (8: you shoot yourself)")
        ok("fumble table 8" in (await pl.inner_text(".ck-res")).lower(),"and shows it")
        # shotgun pattern
        await pl.click(f"[data-act=atk-pick][data-id='{W['Sternmeyer Stakeout 10']}']");await pl.click("[data-act=atk-dv][data-v='20']");await pl.wait_for_timeout(100)
        ok("2m wide, 3d6" in (await pl.inner_text(".ck-roll")).lower(),"a shotgun at medium range: a 2m pattern of 3D6")
        await pl.evaluate("d10x=()=>[10,10];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        ok((await pl.evaluate("Dice.log[0].detail")).endswith("3D6 each"),"the pattern's damage is 3D6")
        # autoshotgun
        await pl.click(f"[data-act=atk-pick][data-id='{W['Arasaka Rapid Assault 12']}']");await pl.click("[data-act=atk-mode][data-v=auto]");await pl.click("[data-act=atk-rounds][data-d='1']");await pl.wait_for_timeout(100)
        ok("3 autoshotgun blasts" in (await pl.inner_text(".ck-roll .mono")).lower() and await pl.evaluate(f"atkMods(curChar(),atkWeapon(curChar(),'{W['Arasaka Rapid Assault 12']}'),ui.atk).find(m=>/blasts/.test(m[0]))[1]")==-4,"three autoshotgun blasts: −2 for each after the first")
        # suppressive fire with an SMG
        smg=await pl.evaluate("curChar().weapons.find(w=>w.type==='SMG').id")
        await pl.click(f"[data-act=atk-pick][data-id='{smg}']");await pl.click("[data-act=atk-mode][data-v=suppress]");await pl.wait_for_timeout(100)
        await pl.evaluate("curChar().weapons.find(w=>w.id==='"+smg+"').ammo=30;ui.atk.rounds=20;ui.atk.width=2;renderModal()")
        a0=await pl.evaluate(f"curChar().weapons.find(w=>w.id==='{smg}').ammo")
        await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        e=await pl.evaluate("Dice.log[0]");print(e,await pl.evaluate(f"curChar().weapons.find(w=>w.id==='{smg}')"));ok(e["label"].startswith("Suppressive") and e["total"]==10,"20 rounds into a 2m zone: crossing it needs 10")
        ok(await pl.evaluate(f"curChar().weapons.find(w=>w.id==='{smg}').ammo")==10,"and it uses the 20 rounds")
        await pl.screenshot(path=shot("atk-suppress.png"))
        # grenade: miss and scatter
        await pl.click(f"[data-act=atk-pick][data-id='{W['Grenade (fragmentation)']}']");await pl.wait_for_timeout(100)
        body=await pl.evaluate("calc(curChar()).eff.BODY");ok(f"10 × body = {10*body}m" in (await pl.inner_text(".ck-roll")).lower(),"a thrown grenade reaches 10 × BODY")
        await pl.click("[data-act=atk-dv][data-v='30']");await pl.evaluate("d10x=()=>[2];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        r=await pl.evaluate("ui.atk.last");print(r["area"]);ok(r["area"] and "misses" in r["area"]["where"] and "m from the target" in r["area"]["where"] and r["area"]["dmg"] is not None,"a missed grenade scatters (direction and meters) and still goes off")
        ok("5m" in r["area"]["where"] and "7D6" in r["area"]["dmgText"],"frag: 7D6 to everything within 5m")
        ok(await pl.evaluate(f"curChar().weapons.find(w=>w.id==='{W['Grenade (fragmentation)']}').ammo")==1,"one grenade used")
        await pl.screenshot(path=shot("atk-grenade.png"))
        # launcher fires the last grenade
        await pl.click(f"[data-act=atk-pick][data-id='{W['Grenade launcher']}']");await pl.wait_for_timeout(100)
        await pl.evaluate("d10x=()=>[10,9];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        r=await pl.evaluate("ui.atk.last");ok(r["area"]["where"].startswith("Right on target") and await pl.evaluate(f"curChar().weapons.find(w=>w.id==='{W['Grenade (fragmentation)']}').ammo")==0,"the launcher fires a grenade you carry, on target")
        await pl.select_option("select[data-act-change=atk-gid]",W['Grenade (gas)']);await pl.select_option("select[data-act-change=atk-gas]","Nerve gas");await pl.wait_for_timeout(100)
        await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        r=await pl.evaluate("ui.atk.last");ok("8D10" in r["area"]["dmgText"] and "half" in r["area"]["dmgText"],"nerve gas: 8D10, halved on a save")
        # C-6, placed, 2 kg
        await pl.click(f"[data-act=atk-pick][data-id='{W['C-6 plastic explosive (1kg)']}']");await pl.click("[data-act=atk-units][data-d='1']");await pl.wait_for_timeout(100)
        ok("10m radius" in (await pl.inner_text(".atk-area")).lower() and "set it off" in (await pl.inner_text(".ck-go")).lower(),"2 kg of C-6, placed: 10m blast, no attack roll")
        await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        r=await pl.evaluate("ui.atk.last");ok("whole body" in r["area"]["dmgText"] and "within 10m" in r["area"]["where"] and await pl.evaluate(f"curChar().weapons.find(w=>w.id==='{W['C-6 plastic explosive (1kg)']}').ammo")==0,"it goes off: 8D10 to the whole body within 10m, both kilos used")
        # Molotov: burns for the next turns? no; incendiary does. Molotov is 2D10 once
        await pl.click(f"[data-act=atk-pick][data-id='{W['Molotov cocktail']}']");await pl.evaluate("d10x=()=>[10,5];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        ok("2D10" in await pl.evaluate("ui.atk.last.area.dmgText"),"a Molotov: 2D10")
        # melee against the defender, mono-edge
        await pl.click(f"[data-act=atk-pick][data-id='{W['Monokatana']}']");await pl.wait_for_timeout(100)
        await pl.fill("input[data-atkui=def]","8");await pl.evaluate("window.__q=[10,3,1];d10x=()=>[window.__q.length?window.__q.shift():5];0")
        await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        r=await pl.evaluate("ui.atk.last");print(r["note"]);ok(r["hit"] and "double damage" in r["note"] and "1/3 sp" in r["note"].lower(),"a mono-edge beats the defender's roll on a natural 10: double damage, armor at 1/3")
        await pl.evaluate("d10x=()=>[1];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        ok(await pl.evaluate("ui.atk.last.broke"),"a mono-edge fumble breaks the blade")
        await pl.evaluate("window.__q=[3,9];d10x=()=>[window.__q.length?window.__q.shift():5];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        ok(await pl.evaluate("ui.atk.last.hit")==False and "beats your" in await pl.evaluate("ui.atk.last.note"),"a better defender's roll wins")
        # martial arts
        await pl.evaluate("(()=>{const c=curChar();c.customSkills.push({n:'Martial Art: Karate',s:'REF',m:2});c.skills['Martial Art: Karate']={c:0,p:6,b:0};saveChar(c,true)})()")
        await pl.click("[data-act=atk-pick][data-id='_kick']");await pl.wait_for_timeout(100)
        m=await pl.evaluate("atkMods(curChar(),atkWeapon(curChar(),'_kick'),ui.atk)");print(m)
        ok(any(x[0].startswith("Martial Art: Karate") for x in m) and any("Karate key attack (Kick)" in x[0] and x[1]==2 for x in m),"a karate kick uses Martial Art: Karate with the +2 key-attack bonus")
        bon=await pl.evaluate("atkDmgBonus(curChar(),atkWeapon(curChar(),'_kick'),ui.atk)");mb=await pl.evaluate("calc(curChar()).melee")
        ok(bon==mb+6,"martial arts add their level (6) to damage, with the melee bonus (%d)"%bon)
        await pl.click("[data-act=atk-move][data-v=Throw]");await pl.wait_for_timeout(100)
        ok("grapple first" in (await pl.inner_text(".ck-roll")).lower(),"a throw needs a grapple first")
        await pl.click("[data-act=atk-move][data-v=Hold]");await pl.click("[data-act=atk-dmg]");await pl.wait_for_timeout(100)
        ok(await pl.evaluate("ui.atk.last.hits.length")==0,"a hold does no damage")
        await pl.screenshot(path=shot("atk-karate.png"))
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        # sheet: cover and fast draw
        await pl.fill("#dmg-amt","30");await pl.select_option("select[data-act-change=dmg-loc]","torso");await pl.select_option("select[data-act-change=dmg-cover]",label="Behind brick wall (SP 25)")
        await pl.click("[data-act=dmg-calc]");await pl.wait_for_timeout(100)
        sp=await pl.evaluate("spAt(curChar(),'torso')");exp=await pl.evaluate(f"hitSP({sp},{{cover:25}})")
        ok(f"SP {exp}" in await pl.evaluate("ui.dmg.result.text"),"damage behind a brick wall uses armor + cover (SP %d)"%exp)
        await pl.click("[data-act=roll-init][data-fd='1']");await pl.wait_for_timeout(100)
        ok(await pl.evaluate("Dice.log[0].label")=="Initiative (fast draw)" and "fastdraw" in await pl.evaluate("ui.atk.sits"),"fast draw initiative turns the −3 on in the attack window")
        # skill check fumble on a TECH skill
        await pl.evaluate("d10x=()=>[1];window.__r=Math.random;Math.random=()=>0.95;0")
        e=await pl.evaluate("Dice.check('Basic Tech (TECH)',5,{})");await pl.evaluate("Math.random=window.__r")
        ok(e["fumbleRoll"]["area"]=="tech" and "beyond repair" in e["fumbleRoll"]["text"],"a TECH fumble rolls the Tech table (10: beyond repair)")

        # ---------------- GM ----------------
        gm=await page(b,"GM","gm.html");gm.set_default_timeout(8000)
        await gm.click("nav [data-act=tab][data-t=encounter]");await gm.wait_for_timeout(150)
        await gm.select_option("#enc-npc","t-corpsec");await gm.fill("#enc-count","2");await gm.click("[data-act=enc-add-npc]");await gm.wait_for_timeout(200)
        cids=await gm.evaluate("st.encounter.list.map(x=>x.cid)")
        await gm.check(f"input[data-act-change=cb-fd][data-cid='{cids[0]}']");await gm.wait_for_timeout(100)
        await gm.evaluate("d10x=()=>[5];0");await gm.click("[data-act=enc-init]");await gm.wait_for_timeout(150)
        ini=await gm.evaluate(f"(()=>{{const l=st.encounter.list;return [l.find(x=>x.cid==='{cids[0]}').init,l.find(x=>x.cid==='{cids[1]}').init]}})()")
        ok(ini[0]==ini[1]+3,"fast draw: +3 initiative in the tracker %s"%ini)
        # cover on an NPC: SP 14 torso armor behind a car door (10)
        await gm.select_option(f"select[data-act-change=cb-cover][data-cid='{cids[1]}']",label="Car body, door · SP 10");await gm.wait_for_timeout(100)
        ok(await gm.evaluate(f"st.encounter.list.find(x=>x.cid==='{cids[1]}').cover")==10,"cover is set on the combatant")
        await gm.fill(f"#dmg-{cids[1]}","20");await gm.select_option(f"select[data-act-change=cb-loc][data-cid='{cids[1]}']","torso");await gm.click(f"[data-act=cb-hit][data-cid='{cids[1]}']");await gm.wait_for_timeout(150)
        last=await gm.evaluate(f"st.encounter.list.find(x=>x.cid==='{cids[1]}').last");print(last)
        ok("cover SP 10" in last and "SP 19" in last,"a hit through a car door: armor 14 + cover 10 = SP 19 by the proportional rule")
        await gm.check(f"input[data-act-change=cb-mono][data-cid='{cids[1]}']");await gm.fill(f"#dmg-{cids[1]}","10");await gm.click(f"[data-act=cb-hit][data-cid='{cids[1]}']");await gm.wait_for_timeout(150)
        last=await gm.evaluate(f"st.encounter.list.find(x=>x.cid==='{cids[1]}').last");print(last);ok("mono-edge" in last,"mono-edge hits cut the armor")
        # parry and dodge
        await gm.select_option(f"select[data-act-change=cb-def][data-cid='{cids[0]}']","parry");await gm.wait_for_timeout(100)
        await gm.click(f"[data-act=cb-parry][data-cid='{cids[0]}'][data-n='9']");await gm.wait_for_timeout(100)
        ok("blade hold" in (await gm.evaluate("Dice.log[0].label")),"a parrying blade saves on 9 or less")
        await gm.select_option(f"select[data-act-change=cb-def][data-cid='{cids[0]}']","dodge");await gm.wait_for_timeout(100)
        ok("−2 to melee attacks" in await gm.inner_text(f"#cb-{cids[0]}"),"a dodger shows the −2")
        # fire zone and scatter
        await gm.fill("#enc-zone","13");await gm.wait_for_timeout(600)
        await gm.evaluate("d10x=()=>[1];0");await gm.click(f"[data-act=cb-zone][data-cid='{cids[0]}']");await gm.wait_for_timeout(150)
        e=await gm.evaluate("Dice.log[0]");print(e);ok("fire zone" in e["label"] and e["tags"][0]["t"].endswith(" hit"),"crossing a fire zone: a failed save takes 1D6 rounds")
        await gm.click("[data-act=enc-scatter]");await gm.wait_for_timeout(100)
        ok(await gm.evaluate("Dice.log[0].label")=="Grenade scatter" and "m from the target" in await gm.evaluate("Dice.log[0].detail"),"the GM can roll grenade scatter")
        # NPC attack fumble gets the table automatically
        await gm.evaluate("d10x=()=>[1];0")
        b0=await gm.locator(f"#cb-{cids[0]} .wchip .rollbtn").first.click();await gm.wait_for_timeout(150)
        ok("fumble table" in await gm.evaluate("Dice.log[0].detail"),"an NPC's attack fumble rolls the combat fumble table")
        await gm.screenshot(path=shot("gm-encounter.png"),full_page=True)
        await gm.click("nav [data-act=tab][data-t=reference]");await gm.wait_for_timeout(150)
        t=await gm.text_content("main");print([x for x in ["Attack modifiers","Common cover","Area effects","Grenade scatter","Fumbles (combat)","Martial arts key attacks","Suppressive fire"] if x not in t]);ok(all(x in t for x in ["Attack modifiers","Common cover","Area effects","Grenade scatter","Fumbles (combat)","Martial arts key attacks","Suppressive fire"]),"the rules reference has the combat tables")
        ok("Aikido (3)" in t,"martial arts styles with their IP difficulty")
        await gm.screenshot(path=shot("gm-reference.png"),full_page=True)
        print("errors:",errs);ok(not errs,"no page errors")
        await b.close()
    finish()
asyncio.run(main())
